import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for element‑wise addition (float)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for exclusive cumulative sum along a dimension
# (here we compute the prefix‑sum of elements *before* each column)
# ----------------------------------------------------------------------
exclusive_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void exclusive_cumsum_kernel(const float* input, float* output, int batch_size, int num_cols) {
    const int b_idx = blockIdx.x;
    const int col_idx = threadIdx.x;

    if (b_idx < batch_size && col_idx < num_cols) {
        float sum = 0.0f;
        for (int c = 0; c < col_idx; ++c) {
            // input index: b_idx * num_cols + c
            sum += input[b_idx * num_cols + c];
        }
        output[b_idx * num_cols + col_idx] = sum;
    }
}

torch::Tensor exclusive_cumsum_cuda(torch::Tensor x) {
    int batch_size = x.size(0);
    int num_cols   = x.size(1);

    torch::Tensor out = torch.zeros_like(x);

    exclusive_cumsum_kernel<<<batch_size, 256>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, num_cols);

    return out;
}
"""

exclusive_cumsum_cpp_source = "torch::Tensor exclusive_cumsum_cuda(torch::Tensor x);"

exclusive_cumsum = load_inline(
    name="exclusive_cumsum",
    cpp_sources=exclusive_cumsum_cpp_source,
    cuda_sources=exclusive_cumsum_source,
    functions=["exclusive_cumsum_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Optimized model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Optimized version of `Model` that replaces:
      - elementwise addition with the custom CUDA operator `elementwise_add`
      - exclusive cumulative sum along dimension 1 with the custom CUDA operator `exclusive_cumsum`
    """

    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add
        self.exclusive_cumsum = exclusive_cumsum
        self.dim = 1   # dimension along which the exclusive cumulative sum is performed

    def forward(self, x):
        # Exclusive cumulative sum (prefix‑sum of elements *before* each column)
        cumsum = self.exclusive_cumsum(x)   # same shape as input
        zeros = torch.zeros_like(x)

        return torch.cat((zeros, cumsum), dim=self.dim)

def get_inputs():
    """Return two random tensors of shape (batch_size, 1)."""
    batch_size = 32768
    x = torch.randn(batch_size, 1).cuda()
    y = torch.randn(batch_size, 1).cuda()
    return [x, y]

